// App members. User-provided brand image is embedded unchanged.
Com<ID2D1Bitmap> studioBrand;
float studioBrandTextWidth=0;
void paintStudioBrand(Rect r,bool details=false){if(!studioBrand)studioBrand=renderer.resource(204);if(!details&&studioBrandTextWidth<=0){Com<IDWriteTextFormat> format;Com<IDWriteTextLayout> layout;const std::wstring text=L"© White Studio · SNUWCANVAS";check(renderer.write->CreateTextFormat(L"Noto Sans KR",renderer.fonts.Get(),DWRITE_FONT_WEIGHT_NORMAL,DWRITE_FONT_STYLE_NORMAL,DWRITE_FONT_STRETCH_NORMAL,11,L"ko-KR",&format),"Brand font");check(renderer.write->CreateTextLayout(text.c_str(),UINT32(text.size()),format.Get(),1000,24,&layout),"Brand layout");DWRITE_TEXT_METRICS metrics{};check(layout->GetMetrics(&metrics),"Brand metrics");studioBrandTextWidth=metrics.width;}float size=details?40.f:24.f,x=details?r.x:r.x+std::max(0.f,(r.w-size-10-studioBrandTextWidth)/2);renderer.bitmap(studioBrand.Get(),{x,r.y,size,size});float textX=x+size+10,available=std::max(1.f,r.x+r.w-textX);if(details){label(L"White Studio",{textX,r.y,available,25},true,0xeeeeee,18);label(L"SNUWCANVAS "+wide(CLIENT_DISPLAY_VERSION)+L" · © White Studio. All rights reserved.",{textX,r.y+29,available,25},false,0xccccd0,11);}else label(L"© White Studio · SNUWCANVAS",{textX,r.y,available,24},false,0xccccd0,11);}
